// TikTok follows tiktok cal.xlsx; no sales VAT deduction in the supplied formula.
function tiktokCalc(sp,r){if(!Number.isFinite(sp)||sp<=0)throw Error('Selling price must be greater than zero.');for(const k of ['cost','fulfil','shipping'])if(!Number.isFinite(r[k])||r[k]<0)throw Error('Enter a valid non-negative '+k+' amount.');if(!Number.isFinite(r.adRate)||r.adRate<0||r.adRate>100)throw Error('Smart Promotion must be between 0 and 100%.');const commission=round(sp*.09),additionalCommission=round(sp*.01),advertising=round(sp*r.adRate/100),fees=commission+additionalCommission+advertising+r.fulfil,costs=r.cost+r.shipping,profit=sp-fees-costs;return{workbook:true,channel:'tiktok',sp,revenue:sp,netRevenue:sp,vat:0,commission,additionalCommission,advertising,fulfil:r.fulfil,shipping:r.shipping,cost:r.cost,costs,fees,profit,margin:profit/sp*100};}
function tiktokPrice(r,target,style){if(!Number.isFinite(target)||target>=100)throw Error('Target margin must be below 100%; negative margins are allowed.');tiktokCalc(1,r);const slope=1-.09-.01-r.adRate/100-target/100;if(slope<=0)throw Error('These fees leave no price that meets this target.');let cents=snap(Math.max(1,Math.ceil(Math.max(0,r.cost+r.shipping+r.fulfil-.015)/slope*100-1e-8)),style);for(;cents<=10000000;cents=snap(cents+1,style)){const a=tiktokCalc(cents/100,r);if(a.margin+1e-9>=target)return a;}throw Error('No price meets this target within £100,000.');}
function syncTikTokUI(){$('fulfilLabel').hidden=false;$('fulfilLabel').firstChild.textContent='TikTok shipping fee';$('fulfilLabel').querySelector('small').textContent='Separate from your seller shipping cost.';$('quantityField').hidden=true;$('adField').hidden=false;$('adField').firstChild.textContent='Smart Promotion %';$('shipping').closest('label').firstChild.textContent='Seller shipping cost';$('spField').firstChild.textContent='Current Selling Price';$('costInfo').textContent='Matches your TikTok spreadsheet: 9% commission + 1% additional commission + Smart Promotion, each rounded separately. TikTok shipping, product cost and seller shipping are deducted. No VAT deduction; margin is profit ÷ selling price.';$('notice').innerHTML='<b>TikTok UK · Your spreadsheet calculations</b> — Smart Promotion defaults to 5%. TikTok shipping and seller shipping are separate costs.';}
function showTikTokResult(a){$('result').innerHTML=`<div class="result"><div class="eyebrow">${mode==='target'?'RECOMMENDED SELLING PRICE':'CURRENT SELLING PRICE'}</div><div class="price">${money(a.sp)}</div><p>TikTok UK · Margin on selling price</p></div><div class="metrics"><div class="metric"><small>NET MARGIN</small><strong class="${a.profit>=0?'positive':'negative'}">${a.margin.toFixed(2)}%</strong></div><div class="metric"><small>NET PROFIT</small><strong>${money(a.profit)}</strong></div><div class="metric"><small>TOTAL TIKTOK FEES</small><strong>${money(a.fees)}</strong></div></div><div class="card"><h2>Fee breakdown</h2>${[['Selling price',a.sp],['Commission fee',-a.commission],['Additional commission',-a.additionalCommission],['Smart Promotion',-a.advertising],['TikTok shipping fee',-a.fulfil],['Cost of goods',-a.cost],['Seller shipping',-a.shipping]].map(([l,v])=>`<div class="row"><span>${l}</span><b>${money(v)}</b></div>`).join('')}<div class="row total"><span>Net Profit</span><b>${money(a.profit)}</b></div><p class="muted">Matches your TikTok spreadsheet. No VAT deduction.</p></div>`;}

// Custom market picker: real SVG flags in both the selected value and options.
const marketFlags={"UK": "data:image/svg+xml;base64,", "FR": "data:image/svg+xml;base64,PHN2ZyB4bWxucz0iaHR0cDovL3d3dy53My5vcmcvMjAwMC9zdmciIHZpZXdCb3g9IjAgMCAzMCAyMCI+PHJlY3Qgd2lkdGg9IjEwIiBoZWlnaHQ9IjIwIiBmaWxsPSIjMDAyMzk1Ii8+PHJlY3QgeD0iMTAiIHdpZHRoPSIxMCIgaGVpZ2h0PSIyMCIgZmlsbD0id2hpdGUiLz48cmVjdCB4PSIyMCIgd2lkdGg9IjEwIiBoZWlnaHQ9IjIwIiBmaWxsPSIjZWQyOTM5Ii8+PC9zdmc+", "DE": "data:image/svg+xml;base64,PHN2ZyB4bWxucz0iaHR0cDovL3d3dy53My5vcmcvMjAwMC9zdmciIHZpZXdCb3g9IjAgMCAzMCAyMCI+PHJlY3Qgd2lkdGg9IjMwIiBoZWlnaHQ9IjciIGZpbGw9IiMxMTEiLz48cmVjdCB5PSI3IiB3aWR0aD0iMzAiIGhlaWdodD0iNyIgZmlsbD0iI2QwMCIvPjxyZWN0IHk9IjE0IiB3aWR0aD0iMzAiIGhlaWdodD0iNiIgZmlsbD0iI2ZmY2UwMCIvPjwvc3ZnPg=="};
const marketNames={UK:'United Kingdom · GBP',FR:'France · EUR',DE:'Germany · EUR'};
const marketSelect=$('market');marketSelect.hidden=true;
const marketPicker=document.createElement('div');marketPicker.className='market-picker';
marketPicker.innerHTML='<button type="button" class="market-picker-trigger" aria-haspopup="listbox" aria-expanded="false" aria-label="Market"><span></span><b aria-hidden="true">▾</b></button><div class="market-picker-menu" role="listbox" aria-label="Country" hidden></div>';
marketSelect.after(marketPicker);const marketTrigger=marketPicker.querySelector('button'),marketMenu=marketPicker.querySelector('.market-picker-menu');
function renderMarketPicker(){marketTrigger.querySelector('span').innerHTML=`<img src="${marketFlags[marketSelect.value]}" alt="">${marketNames[marketSelect.value]}`;marketMenu.innerHTML=[...marketSelect.options].map(o=>`<button type="button" role="option" aria-selected="${o.value===marketSelect.value}" data-market-value="${o.value}"><img src="${marketFlags[o.value]}" alt="">${marketNames[o.value]}${o.value===marketSelect.value?'<b aria-hidden="true">✓</b>':''}</button>`).join('');}
function closeMarketPicker(){marketMenu.hidden=true;marketTrigger.setAttribute('aria-expanded','false');}
marketTrigger.onclick=()=>{const opening=marketMenu.hidden;marketMenu.hidden=!opening;marketTrigger.setAttribute('aria-expanded',String(opening));if(opening)marketMenu.querySelector('[aria-selected="true"]')?.focus();};
marketMenu.onclick=e=>{const option=e.target.closest('[data-market-value]');if(!option)return;marketSelect.value=option.dataset.marketValue;marketSelect.dispatchEvent(new Event('change',{bubbles:true}));renderMarketPicker();closeMarketPicker();marketTrigger.focus();};
marketPicker.addEventListener('keydown',e=>{if(e.key==='Escape'){closeMarketPicker();marketTrigger.focus();}if(['ArrowDown','ArrowUp','Home','End'].includes(e.key)){e.preventDefault();marketMenu.hidden=false;marketTrigger.setAttribute('aria-expanded','true');const opts=[...marketMenu.querySelectorAll('button')];let i=opts.indexOf(document.activeElement);i=e.key==='Home'?0:e.key==='End'?opts.length-1:e.key==='ArrowDown'?(i+1)%opts.length:(i-1+opts.length)%opts.length;opts[i]?.focus();}});
document.addEventListener('click',e=>{if(!marketPicker.contains(e.target))closeMarketPicker();});marketPicker.addEventListener('focusout',()=>setTimeout(()=>{if(!marketPicker.contains(document.activeElement))closeMarketPicker();},0));
new MutationObserver(()=>{renderMarketPicker();closeMarketPicker();}).observe(marketSelect,{childList:true});marketSelect.addEventListener('change',renderMarketPicker);renderMarketPicker();

// Separate browser-local single-product inputs for each marketplace and country.
const inputStateKey='marginforge-product-inputs-v1';
const productInputIds=['sku','cost','fulfil','shipping','storage','delivery','other','quantity','adRate','sellerStatus','target','sp','lowest','rounding','amazonCategory'];
let savedProductInputs={};try{const v=JSON.parse(localStorage.getItem(inputStateKey)||'{}');if(v&&typeof v==='object'&&!Array.isArray(v))savedProductInputs=v;}catch{}
let activeInputMarket=channel+'-'+$('market').value;
const initialProductInputs=Object.fromEntries(productInputIds.map(id=>[id,$(id).value]));
function storeProductInputs(){savedProductInputs[activeInputMarket]=Object.fromEntries(productInputIds.map(id=>[id,$(id).value]));try{localStorage.setItem(inputStateKey,JSON.stringify(savedProductInputs));}catch{}}
function restoreProductInputs(key){const c=key.split('-')[0];const fallback=key==='amazon-UK'?initialProductInputs:{...initialProductInputs,sku:'',cost:'0',fulfil:c==='tiktok'?'0.50':c==='amazon'?'2.76':'0',shipping:'0',storage:'0',delivery:'0',other:'0',quantity:'1',adRate:c==='tiktok'?'5':'0',sellerStatus:'top',target:c==='amazon'?'5.15':'10',sp:'19.99',lowest:''};const values=savedProductInputs[key]||fallback;for(const id of productInputIds){const value=values[id]??fallback[id];if(typeof value==='string'||typeof value==='number')$(id).value=String(value);}activeInputMarket=key;}
$('channels').onclick=e=>{const button=e.target.closest('[data-channel]');if(!button||button.dataset.channel===channel)return;storeProductInputs();channel=button.dataset.channel;syncMarketOptions();restoreProductInputs(channel+'-'+$('market').value);refresh();scheduleCalculation();};
$('market').onchange=()=>{storeProductInputs();restoreProductInputs(channel+'-'+$('market').value);refresh();scheduleCalculation();};
document.addEventListener('input',e=>{if(productInputIds.includes(e.target.id))storeProductInputs();});document.addEventListener('change',e=>{if(productInputIds.includes(e.target.id))storeProductInputs();});
const originalProductReset=$('reset').onclick;$('reset').onclick=()=>{originalProductReset();if(channel==='tiktok'){$('fulfil').value=.5;$('adRate').value=5;}storeProductInputs();scheduleCalculation();};
function marginBasisLabel(){return ['ebay','onbuy','shopify'].includes(channel)?'Margin basis: revenue excluding VAT':'Margin basis: selling price';}
const feeModelNote=document.createElement('div');feeModelNote.className='fee-model-note';$('notice').after(feeModelNote);
const refreshBeforeModelNote=refresh;refresh=function(){refreshBeforeModelNote();feeModelNote.innerHTML='<span>'+marginBasisLabel()+'</span><span>Fee model v2.1 · Configured 4 Oct 2026</span>';};
const showResultBeforeBasis=showResult;showResult=function(a){showResultBeforeBasis(a);const note=document.createElement('p');note.className='margin-basis-note';note.textContent=['ebay','onbuy','shopify'].includes(a.channel)?'Margin = profit ÷ revenue excluding VAT':'Margin = profit ÷ selling price';$('result').querySelector('.metrics')?.before(note);};
restoreProductInputs(activeInputMarket);refresh();scheduleCalculation();

// Margin Engine highlights its calculated outcome; Selling Price Engine keeps price first.
const showResultBeforeMarginHeadline=showResult;
showResult=function(a){showResultBeforeMarginHeadline(a);if(mode!=='actual')return;const hero=$('result').querySelector('.result');if(!hero)return;hero.classList.add('margin-result');const title=hero.querySelector('.eyebrow'),value=hero.querySelector('.price');if(title)title.textContent='CALCULATED MARGIN';if(value){value.textContent=a.margin.toFixed(2)+'%';value.classList.add(a.profit>=0?'positive':'negative');}const priceContext=document.createElement('p');priceContext.className='entered-price-context';priceContext.textContent='At entered selling price '+money(a.sp);value?.after(priceContext);};

